// Third-party data for the About screens (t32-e75).
//
// The lists are generated by scripts/about/gen-third-party.mjs and committed:
//   - third-party.web.json            npm packages, fonts and icons (imported here)
//   - mw-server src/about/third-party.crates.json  Rust crates (the server serves it)
//   - texts/<0-f>.json                every licence text once, by id, for both lists,
//                                     in 16 shards by the id's first character
// The texts add up to about 1.3 MB, so each shard (50-110 KB) is its own chunk,
// loaded the first time a text in it is opened; the service worker keeps
// /assets/, so an opened text works offline after that.

import webDoc from './third-party.web.json';

export type ThirdPartyKind = 'crate' | 'npm' | 'font' | 'icons';

export interface LicenceTextRef {
  /** Key into the texts file. */
  id: string;
  /** File name in the package, e.g. `LICENSE-MIT`. */
  file?: string;
  /** Set instead of `file` when the package ships no licence file: the SPDX id
   *  whose standard text is shown. */
  standard?: string;
}

export interface ThirdPartyEntry {
  kind: ThirdPartyKind;
  name: string;
  version?: string;
  /** SPDX expression as declared, e.g. `MIT OR Apache-2.0`. */
  licence: string;
  repository?: string;
  homepage?: string;
  texts: LicenceTextRef[];
  /** Crates: which shipped parts use it (`server`, `web`, `plugins`, `desktop`, `mobile`). */
  artifacts?: string[];
  /** Assets: `bundled`, `fonts-pull` or `first-party`. */
  note?: string;
}

/** An https link, or undefined. The data is generated, but crate data may come over
 *  the network, so a link is checked again before it becomes an href. */
export function safeHref(raw: unknown): string | undefined {
  if (typeof raw !== 'string') return undefined;
  try {
    const u = new URL(raw);
    return u.protocol === 'https:' && !u.username && !u.password ? u.href : undefined;
  } catch {
    return undefined;
  }
}

/** The licence ids in an SPDX expression, without operators, exceptions or `+`. */
export function licenceIdsOf(expr: string): string[] {
  const out: string[] = [];
  let afterWith = false;
  for (const tok of expr.match(/[^\s()]+/g) ?? []) {
    const up = tok.toUpperCase();
    if (up === 'WITH') {
      afterWith = true;
      continue;
    }
    if (up === 'OR' || up === 'AND') continue;
    if (afterWith) {
      afterWith = false;
      continue;
    }
    const id = tok.replace(/\+$/, '');
    if (!out.includes(id)) out.push(id);
  }
  return out;
}

function str(v: unknown): string | undefined {
  return typeof v === 'string' && v !== '' ? v : undefined;
}

function toEntry(raw: unknown, kind: ThirdPartyKind): ThirdPartyEntry | null {
  if (!raw || typeof raw !== 'object') return null;
  const r = raw as Record<string, unknown>;
  const name = str(r.name);
  if (!name) return null;
  const texts = Array.isArray(r.texts)
    ? r.texts.flatMap((t): LicenceTextRef[] => {
        if (!t || typeof t !== 'object') return [];
        const o = t as Record<string, unknown>;
        const id = str(o.id);
        if (!id) return [];
        const ref: LicenceTextRef = { id };
        const file = str(o.file);
        const standard = str(o.standard);
        if (file) ref.file = file;
        if (standard) ref.standard = standard;
        return [ref];
      })
    : [];
  const e: ThirdPartyEntry = { kind, name, licence: str(r.licence) ?? '', texts };
  const version = str(r.version);
  const repository = safeHref(r.repository);
  const homepage = safeHref(r.homepage);
  const note = str(r.note);
  if (version) e.version = version;
  if (repository) e.repository = repository;
  if (homepage) e.homepage = homepage;
  if (note) e.note = note;
  if (Array.isArray(r.artifacts)) e.artifacts = r.artifacts.filter((a): a is string => typeof a === 'string');
  return e;
}

function packagesOf(doc: unknown): unknown[] {
  const p = doc && typeof doc === 'object' ? (doc as { packages?: unknown }).packages : undefined;
  return Array.isArray(p) ? p : [];
}

/** npm packages, then the fonts and icons, from the committed web list. */
export function webEntries(doc: unknown = webDoc): ThirdPartyEntry[] {
  const assets = doc && typeof doc === 'object' ? (doc as { assets?: unknown }).assets : undefined;
  const assetEntries = (Array.isArray(assets) ? assets : []).map((a) => {
    const k = (a as { kind?: unknown } | null)?.kind;
    return toEntry(a, k === 'icons' ? 'icons' : 'font');
  });
  return [...packagesOf(doc).map((p) => toEntry(p, 'npm')), ...assetEntries].filter(
    (e): e is ThirdPartyEntry => e !== null,
  );
}

/** Rust crates from `third-party.crates.json` (as the server serves it). */
export function crateEntries(doc: unknown): ThirdPartyEntry[] {
  return packagesOf(doc)
    .map((p) => toEntry(p, 'crate'))
    .filter((e): e is ThirdPartyEntry => e !== null);
}

const shardLoaders = import.meta.glob<{ default: Record<string, string> }>('./texts/*.json');
const shardPromises = new Map<string, Promise<Record<string, string>>>();

function loadShard(h: string): Promise<Record<string, string>> {
  let p = shardPromises.get(h);
  if (!p) {
    const loader = shardLoaders[`./texts/${h}.json`];
    p = loader
      ? loader().then(
          (m) => m.default,
          (err: unknown) => {
            shardPromises.delete(h); // a failed load can be retried
            throw err;
          },
        )
      : Promise.resolve({});
    shardPromises.set(h, p);
  }
  return p;
}

/** The licence texts with these ids (from the shards that hold them; each loaded once). */
export async function loadLicenceTexts(ids: readonly string[]): Promise<Record<string, string>> {
  const shards = [...new Set(ids.map((id) => id.charAt(0)))];
  const loaded = await Promise.all(shards.map(loadShard));
  const out: Record<string, string> = {};
  for (const id of ids) {
    const text = loaded[shards.indexOf(id.charAt(0))]?.[id];
    if (text !== undefined) out[id] = text;
  }
  return out;
}
